// Adapted from Eight Aces dist/sw.js. Generated by scripts/build-offline.mjs.
const cachePrefix = 'gomoku-offline-' + self.registration.scope;
const cacheName = cachePrefix + '1.1.0';
const scope = self.registration.scope;
const assetNames = [
  "achievements.js",
  "andromeda-portrait.webp",
  "app.js",
  "apple-touch-icon.png",
  "backup-strings.js",
  "computer-worker.js",
  "computer.js",
  "copper-portrait.webp",
  "copper-table.webp",
  "credits.html",
  "engine.js",
  "favicon-16.png",
  "favicon-32.png",
  "favicon-64.png",
  "favicon.ico",
  "favicon.svg",
  "games-chest-menu.css",
  "games-chest-menu.js",
  "i18n.js",
  "icon-192.png",
  "icon-512.png",
  "icon-maskable.png",
  "index.html",
  "locales.js",
  "logo.png",
  "logo.svg",
  "manifest.webmanifest",
  "orange-grove.webp",
  "preferences-strings.js",
  "profile-storage.js",
  "progress-backup.js",
  "pwa.js",
  "results.js",
  "settings-gear.svg",
  "settings-strings.js",
  "settings.css",
  "shared-game.css",
  "shared-palettes.css",
  "shared-preferences.js",
  "shared-progress-backup.js",
  "shared-settings.css",
  "shared-victory.css",
  "shared-victory.js",
  "starry-sky.webp",
  "strings.js",
  "style.css",
  "toolbar.css",
  "version.json"
];
const assets = new Set(assetNames.map(name => new URL(name, scope).href));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(cacheName);
    await cache.addAll([...assets].map(url => new Request(url, { cache: 'reload' })));
  })());
  // No skipWaiting: existing games continue using their complete release.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith(cachePrefix) && key !== cacheName)
      .map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  url.search = '';
  url.hash = '';
  const key = url.href === scope ? new URL('index.html', scope).href : url.href;
  // Only this game's explicit resources; external links and analytics stay online.
  if (!assets.has(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(cacheName);
    return await cache.match(key) ?? fetch(event.request);
  })());
});
